mapper.insert:
INSERT INTO tdm45_manl_relate_ics
       ( tdm45_manl_relate_ics_id, tdm45_manl_id, tdm45_ics_class_tree_id )
SELECT f_create_seq(), #{manlId}, #{icsClassTreeId}
 WHERE NOT EXISTS (
       SELECT 1
         FROM tdm45_manl_relate_ics
        WHERE tdm45_manl_id = #{manlId}
          AND tdm45_ics_class_tree_id = #{icsClassTreeId}
 )

mapper.delete:
DELETE FROM tdm45_manl_relate_ics
 WHERE tdm45_manl_relate_ics_id = #{manlRelateIcsId}
   AND tdm45_ics_class_tree_id = #{icsClassTreeId}
